92:     /// Determine which function to use as entry point, based on command-line arguments and kani-metadata.
93:     pub fn determine_targets<'a>(
94:         &self,
95:         compiler_filtered_harnesses: Vec<&'a HarnessMetadata>,
96:     ) -> Result<Vec<&'a HarnessMetadata>> {
97:         let harness_filters = BTreeSet::from_iter(self.args.harnesses.iter());
98: 
99:         // For dev builds, re-filter the harnesses to double check filtering in the compiler
100:         // and ensure we're doing the minimal harness codegen possible. That filtering happens in
101:         // the `kani-compiler/src/kani_middle/codegen_units.rs` file's `determine_targets` function.
102:         // The compiler filters only manual harnesses and keeps every automatic harness, and
103:         // `find_proof_harnesses` skips automatic harnesses, so compare the manual harnesses only.
104:         // This detects retained manual harnesses that do not satisfy the filter. It does not check
105:         // the selection of automatic harnesses.
106:         if cfg!(debug_assertions) && !harness_filters.is_empty() {
107:             let manual_harnesses: Vec<&HarnessMetadata> = compiler_filtered_harnesses
108:                 .iter()
109:                 .copied()
110:                 .filter(|harness| !harness.is_automatically_generated)
111:                 .collect();
112:             let filtered_harnesses: Vec<&HarnessMetadata> =
113:                 find_proof_harnesses(&harness_filters, &manual_harnesses, self.args.exact);
114:             assert_eq!(manual_harnesses, filtered_harnesses);
115:         }
116: 
117:         if self.args.exact {
118:             check_exact_filters_matched(&harness_filters, &compiler_filtered_harnesses)?;
119:         }
120: 
121:         // A `--harness` filter that matches nothing must fail here, before codegen and export.
122:         if !harness_filters.is_empty() && compiler_filtered_harnesses.is_empty() {
123:             return Err(no_harness_match_error(&self.args.harnesses));
124:         }
125: 
126:         Ok(compiler_filtered_harnesses)
127:     }

