244: /// Group the harnesses by their stubs and contract usage.
245: fn group_by_stubs(
246:     tcx: TyCtxt,
247:     all_harnesses: &HashMap<Harness, HarnessMetadata>,
248: ) -> Vec<CodegenUnit> {
249:     let mut per_stubs: HashMap<_, CodegenUnit> = HashMap::default();
250:     for (harness, metadata) in all_harnesses {
251:         let stub_ids = harness_stub_map(tcx, *harness, metadata);
252:         let contracts = extract_contracts(tcx, *harness);
253:         let stub_map = stub_ids
254:             .iter()
255:             .map(|(k, v)| (tcx.def_path_hash(*k), tcx.def_path_hash(*v)))
256:             .collect::<BTreeMap<_, _>>();
257:         let key = (contracts, stub_map);
258:         if let Some(unit) = per_stubs.get_mut(&key) {
259:             unit.harnesses.push(*harness);
260:         } else {
261:             let stubs = stub_ids
262:                 .iter()
263:                 .map(|(from, to)| (stub_def(tcx, *from), stub_def(tcx, *to)))
264:                 .collect::<HashMap<_, _>>();
265:             let stubs = apply_transitivity(tcx, *harness, stubs);
266:             per_stubs.insert(key, CodegenUnit { stubs, harnesses: vec![*harness] });
267:         }
268:     }
269:     per_stubs.into_values().collect()
270: }
