278: /// Extract the contract related usages.
279: ///
280: /// Note that any error interpreting the result is emitted, but we delay aborting, so we emit as
281: /// many errors as possible.
282: fn extract_contracts(tcx: TyCtxt, harness: Harness) -> BTreeSet<ContractUsage> {
283:     let def = harness.def;
284:     let mut result = BTreeSet::new();
285:     let attributes = KaniAttributes::for_def_id(tcx, def.def_id());
286:     if let Some(target) = attributes.interpret_for_contract_attribute() {
287:         result.insert(ContractUsage::Check(target.def_id().to_index()));
288:     }
289:     for stub in attributes.interpret_stub_verified_attribute() {
290:         result.insert(ContractUsage::Stub(stub.def_id().to_index()));
291:     }
292: 
293:     result
